mapper.select:
SELECT v.*
FROM yak_workflow_version v
JOIN yak_workflow_definition d ON d.id = v.workflow_id
WHERE v.id = #{id}
  AND d.project_id = #{projectId}
LIMIT 1

mapper.update:
UPDATE yak_workflow_version v
JOIN yak_workflow_definition d ON d.id = v.workflow_id
SET v.engine_definition_json = #{engineDefinitionJson}
WHERE v.id = #{id}
  AND d.project_id = #{projectId}
  AND v.engine_definition_json IS NULL

UPDATE yak_workflow_version v
JOIN yak_workflow_definition d ON d.id = v.workflow_id
SET v.runtime_metadata_json = #{runtimeMetadataJson}
WHERE v.id = #{id}
  AND d.project_id = #{projectId}
  AND v.runtime_metadata_json IS NULL
